#include "screens/alarm_delete_confirmation_view.h"
#include "ui/button.h"
#include "ui/theme.h"
ConfirmationDialogView::ConfirmationDialogView(ConfirmationDialogListener& l):listener_(l),overlay_(nullptr),message_(nullptr),confirm_button_(nullptr),confirm_label_(nullptr),config_{}{}
void ConfirmationDialogView::build(lv_obj_t* parent){overlay_=lv_obj_create(parent);lv_obj_remove_style_all(overlay_);lv_obj_set_size(overlay_,LV_PCT(100),LV_PCT(100));lv_obj_set_style_bg_color(overlay_,lv_color_hex(UiTheme::kSurfaceRaised),0);lv_obj_add_flag(overlay_,LV_OBJ_FLAG_HIDDEN);lv_obj_t* dialog=lv_obj_create(overlay_);lv_obj_set_size(dialog,288,180);lv_obj_center(dialog);lv_obj_set_flex_flow(dialog,LV_FLEX_FLOW_COLUMN);lv_obj_set_style_pad_all(dialog,18,0);lv_obj_set_style_pad_row(dialog,16,0);lv_obj_set_flex_align(dialog,LV_FLEX_ALIGN_CENTER,LV_FLEX_ALIGN_CENTER,LV_FLEX_ALIGN_CENTER);message_=lv_label_create(dialog);lv_obj_set_width(message_,LV_PCT(100));lv_obj_set_style_text_align(message_,LV_TEXT_ALIGN_CENTER,0);lv_obj_set_style_text_font(message_,&lv_font_montserrat_20,0);lv_obj_t* actions=lv_obj_create(dialog);lv_obj_remove_style_all(actions);lv_obj_set_size(actions,LV_PCT(100),LV_SIZE_CONTENT);lv_obj_set_flex_flow(actions,LV_FLEX_FLOW_ROW);lv_obj_set_flex_align(actions,LV_FLEX_ALIGN_SPACE_BETWEEN,LV_FLEX_ALIGN_CENTER,LV_FLEX_ALIGN_CENTER);constexpr Ui::ButtonSize s{96,42};Ui::ButtonElements confirm=Ui::createButton(actions,"",UiTheme::kPrimaryButtonStyle,s,onConfirm,this);confirm_button_=confirm.button;confirm_label_=confirm.label;Ui::createButton(actions,"Cancel",UiTheme::kSecondaryButtonStyle,s,onCancel,this);}
void ConfirmationDialogView::show(const ConfirmationDialogConfig& config){config_=config;lv_label_set_text(message_,config.message);lv_label_set_text(confirm_label_,config.confirm_label);lv_obj_set_style_bg_color(confirm_button_,lv_color_hex(config.destructive?0xD64545:UiTheme::kAccent),0);lv_obj_clear_flag(overlay_,LV_OBJ_FLAG_HIDDEN);}void ConfirmationDialogView::hide(){lv_obj_add_flag(overlay_,LV_OBJ_FLAG_HIDDEN);}void ConfirmationDialogView::onConfirm(lv_event_t*e){auto*v=static_cast<ConfirmationDialogView*>(lv_event_get_user_data(e));if(v)v->listener_.onConfirmationConfirmed(v->config_.action,v->config_.alarm_index);}void ConfirmationDialogView::onCancel(lv_event_t*e){auto*v=static_cast<ConfirmationDialogView*>(lv_event_get_user_data(e));if(v)v->listener_.onConfirmationCancelled();}
